challenge_result.investigation_instruction:
{
  "plans": [
    {
      "hypothesis_id": "h1",
      "hypothesis_statement": "The AMF is the source of the failure, having exited and caused a complete loss of UE attachment and all downstream services.",
      "primary_suspect_nf": "amf",
      "probes": [
        {
          "tool": "get_network_status",
          "args_hint": "Check the status of the 'amf' container.",
          "expected_if_hypothesis_holds": "The 'amf' container is reported as 'exited' or another non-running state.",
          "falsifying_observation": "The 'amf' container is reported as 'running'.",
          "conflates_with": []
        },
        {
          "tool": "measure_rtt",
          "args_hint": "From 'nr_gnb' container to the 'amf' container's IP address.",
          "expected_if_hypothesis_holds": "100% packet loss is observed.",
          "falsifying_observation": "Packets are successfully received (e.g., 0% packet loss).",
          "conflates_with": [
            "A network partition between nr_gnb and amf.",
            "A fault in the nr_gnb container's network stack."
          ]
        },
        {
          "tool": "measure_rtt",
          "args_hint": "From 'nr_gnb' container to the 'smf' container's IP address.",
          "expected_if_hypothesis_holds": "Packets are successfully received (e.g., 0% packet loss), indicating the nr_gnb's networking is functional and the path to the core is generally available.",
          "falsifying_observation": "100% packet loss is observed, suggesting a broader network issue or a problem with the nr_gnb container itself.",
          "conflates_with": []
        }
      ],
      "notes": "This plan directly tests the primary claim of the hypothesis: that the AMF container has exited. The RTT probes verify the expected downstream impact (loss of N2 path from RAN) and disambiguate the failure from a general network partition or gNB fault. The partner probe to SMF is chosen because the NA report implies SMF is running but affected downstream (`core.smf.sessions_per_ue_drop`). The `ue_registration` flow, step 2, lists 'N2 SCTP link down' as a failure mode, which this plan tests via transport-level checks."
    }
  ]
}
